const input=$json.body??$json;
const record=input.profit_record??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id&&input.close_id);
const closeoutReady=input.status==="closeout_ready"||input.closeout_ready===true||record.verified===true;
const gross=Number(record.gross_profit??input.gross_profit);
const costs=Number(record.closing_costs??input.closing_costs??0);
const net=Number(record.net_profit??input.net_profit??(Number.isFinite(gross)?gross-costs:NaN));
const margin=Number.isFinite(gross)&&gross!==0?net/gross:null;
const valid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
const sampleSize=Math.max(0,Number(input.historical_sample_size??input.portfolio_sample_size??0));
const avgNet=Number(input.historical_avg_net_profit??input.average_net_profit);
const avgMargin=Number(input.historical_avg_margin??input.average_margin);
const netDelta=Number.isFinite(avgNet)?net-avgNet:null;
const marginDelta=Number.isFinite(avgMargin)&&margin!==null?margin-avgMargin:null;
const performanceSignal=margin!==null&&margin>=0.30?"strong":margin!==null&&margin>=0.15?"acceptable":margin!==null?"weak":"unknown";
let status="performance_record_ready",nextWorkflow="WF-286",humanReview=false;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;}
else if(!closeoutReady){status="closeout_required";nextWorkflow="WF-284";humanReview=true;}
else if(!valid){status="performance_data_invalid";nextWorkflow="WF-284";humanReview=true;}
else if(blockers.length){status="performance_blocked";nextWorkflow="WF-126";humanReview=true;}
const performance={deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,close_id:input.close_id,gross_profit:gross,closing_costs:costs,net_profit:net,profit_margin:margin,historical_sample_size:sampleSize,historical_avg_net_profit:Number.isFinite(avgNet)?avgNet:null,historical_avg_margin:Number.isFinite(avgMargin)?avgMargin:null,net_profit_delta:netDelta,margin_delta:marginDelta,performance_signal:performanceSignal,exit_strategy:record.exit_strategy||input.exit_strategy||"assignment"};
return [{json:{...input,workflow:"WF-285",workflow_name:"Final CRM Closeout → Portfolio Performance Record & Underwriting Feedback Controller",status,portfolio_performance:performance,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"portfolio_performance_underwriting_feedback",idempotency_key:input.idempotency_key||`wf-285:${input.deal_id||"unknown"}:${input.close_id||"none"}:${input.version||1}`}}}];
